import { DesignItem } from "./designBoard";
import { DesignBoardItem, DesignBoardViewProvider } from "./designBoardViewProvider";

function design(index: number): DesignItem {
  return {
    id: `design:${index}`,
    adr_path: `docs/adr/${index}.md`,
    title: `Design ${index}`,
    summary: "",
    status: "proposed",
    created_at: index,
    updated_at: index,
    promotion_status: "not_required",
    materialization_revision: 0,
  };
}

describe("DesignBoardViewProvider", () => {
  it("offers the completed ADR ledger when no designs need attention", () => {
    const provider = new DesignBoardViewProvider();

    const children = provider.getChildren();

    expect(children[0].label).toBe("No ADRs need attention");
    expect(children[1].label).toBe("Browse completed ADRs");
    expect(children[1].command).toMatchObject({ command: "mindleak.design.toggleArchive" });
  });

  it("labels archive rows as the ledger and resets expansion when the mode changes", () => {
    const provider = new DesignBoardViewProvider();
    provider.update(
      Array.from({ length: 25 }, (_, index) => design(index)),
      new Map()
    );
    provider.expand();

    provider.setIncludeArchive(true);

    expect(provider.includeArchive).toBe(true);
    const children = provider.getChildren();
    expect(children[0].label).toBe("25 ADRs in ledger");
    expect(children.filter((item) => item instanceof DesignBoardItem)).toHaveLength(20);
    expect(children.some((item) => item.label === "Browse completed ADRs")).toBe(false);
  });

  it("renders the decision count, a stable cap, and an expand affordance", () => {
    const provider = new DesignBoardViewProvider();
    provider.update(
      Array.from({ length: 25 }, (_, index) => design(index)),
      new Map()
    );

    const collapsed = provider.getChildren();
    expect(collapsed[0].label).toBe("25 awaiting decision");
    expect(collapsed.filter((item) => item instanceof DesignBoardItem)).toHaveLength(20);
    expect(collapsed.at(-1)?.label).toBe("Show 5 more");
    expect(collapsed.at(-1)?.command).toMatchObject({ command: "mindleak.design.expand" });

    provider.expand();
    const expanded = provider.getChildren();
    expect(expanded.filter((item) => item instanceof DesignBoardItem)).toHaveLength(25);
    expect(expanded.at(-1)?.label).toBe("Design 24");
  });

  it("holds deferred visibility as provider state and resets expansion when it changes", () => {
    const provider = new DesignBoardViewProvider();
    provider.update(
      Array.from({ length: 25 }, (_, index) => design(index)),
      new Map()
    );
    provider.expand();

    provider.setIncludeDeferred(true);

    expect(provider.includeDeferred).toBe(true);
    expect(provider.getChildren().filter((item) => item instanceof DesignBoardItem)).toHaveLength(
      20
    );
  });
});
